begin;
create extension if not exists pgcrypto;
create extension if not exists citext;
create type public.workspace_role as enum ('owner','admin','member','viewer');
create type public.account_provider as enum ('gmail','microsoft','zoho','hostinger','imap-smtp');
create type public.lifecycle_status as enum ('active','disabled','revoked','deleted');
create type public.job_status as enum ('pending','running','succeeded','failed','dead','cancelled');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text check(char_length(display_name)<=200), avatar_url text, status lifecycle_status not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspaces (id uuid primary key default gen_random_uuid(), name text not null check(char_length(name) between 1 and 120), slug text not null unique check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'), status lifecycle_status not null default 'active', created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspace_members (workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role workspace_role not null, status lifecycle_status not null default 'active', created_at timestamptz not null default now(), primary key(workspace_id,user_id));
create table public.workspace_invitations (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, email citext not null, role workspace_role not null, token_hash text not null unique, invited_by uuid not null references auth.users(id), expires_at timestamptz not null, accepted_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now(), unique(workspace_id,email));

create table public.email_accounts (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, provider account_provider not null, provider_account_id text not null, email_address citext not null, display_name text not null, status lifecycle_status not null default 'active', last_checked_at timestamptz, last_error_code text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,provider,provider_account_id));
create table public.email_account_settings (email_account_id uuid primary key references public.email_accounts(id) on delete cascade, signature_html text, sender_name text, draft_first boolean not null default false, sync_enabled boolean not null default false, metadata_retention_days int not null default 30 check(metadata_retention_days between 0 and 365), hourly_send_limit int not null default 50 check(hourly_send_limit between 0 and 10000), updated_at timestamptz not null default now());
create table public.provider_credentials (id uuid primary key default gen_random_uuid(), email_account_id uuid not null references public.email_accounts(id) on delete cascade, encrypted_payload jsonb not null, key_version int not null check(key_version>0), status lifecycle_status not null default 'active', expires_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now(), rotated_at timestamptz);
create table public.mailbox_permissions (workspace_id uuid not null references public.workspaces(id) on delete cascade, email_account_id uuid not null references public.email_accounts(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, can_read boolean not null default true, can_send boolean not null default false, can_manage boolean not null default false, primary key(email_account_id,user_id));

create table public.mcp_clients (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null check(char_length(name) between 1 and 120), status lifecycle_status not null default 'active', rate_limit_per_minute int not null default 60 check(rate_limit_per_minute between 1 and 10000), created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.mcp_credentials (id uuid primary key default gen_random_uuid(), mcp_client_id uuid not null references public.mcp_clients(id) on delete cascade, token_prefix text not null, token_hash text not null unique, scopes text[] not null default '{}', status lifecycle_status not null default 'active', expires_at timestamptz, last_used_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now(), check(cardinality(scopes)>0));
create table public.mcp_mailbox_grants (mcp_client_id uuid not null references public.mcp_clients(id) on delete cascade, email_account_id uuid not null references public.email_accounts(id) on delete cascade, created_at timestamptz not null default now(), primary key(mcp_client_id,email_account_id));

create table public.message_index (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, email_account_id uuid not null references public.email_accounts(id) on delete cascade, provider_message_id text not null, provider_thread_id text, folder_id text, subject text, sender text, received_at timestamptz, has_attachments boolean not null default false, indexed_at timestamptz not null default now(), expires_at timestamptz, unique(email_account_id,provider_message_id));
comment on table public.message_index is 'Metadata only; message bodies remain at providers.';
create table public.drafts (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, email_account_id uuid not null references public.email_accounts(id) on delete cascade, provider_draft_id text, envelope jsonb not null, status text not null default 'draft' check(status in ('draft','approved','sent','deleted')), created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.sync_cursors (email_account_id uuid not null references public.email_accounts(id) on delete cascade, cursor_type text not null, cursor_value text not null, updated_at timestamptz not null default now(), primary key(email_account_id,cursor_type));
create table public.jobs (id uuid primary key default gen_random_uuid(), workspace_id uuid references public.workspaces(id) on delete cascade, type text not null, payload jsonb not null default '{}', status job_status not null default 'pending', idempotency_key text unique, attempts int not null default 0, max_attempts int not null default 5, run_after timestamptz not null default now(), lease_owner text, lease_expires_at timestamptz, last_error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.webhook_events (id uuid primary key default gen_random_uuid(), provider account_provider not null, external_event_id text not null, email_account_id uuid references public.email_accounts(id) on delete cascade, payload_hash text not null, received_at timestamptz not null default now(), processed_at timestamptz, status text not null default 'received', unique(provider,external_event_id));
create table public.audit_logs (id bigint generated always as identity primary key, workspace_id uuid references public.workspaces(id) on delete cascade, actor_user_id uuid references auth.users(id), mcp_client_id uuid references public.mcp_clients(id), email_account_id uuid references public.email_accounts(id), action text not null, outcome text not null check(outcome in ('success','denied','failure')), ip_hash text, user_agent text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.workspace_settings (workspace_id uuid primary key references public.workspaces(id) on delete cascade, registration_enabled boolean not null default false, emergency_send_disabled boolean not null default false, hourly_send_limit int not null default 200, defaults jsonb not null default '{}', updated_at timestamptz not null default now());
create table public.system_settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());

create index email_accounts_workspace_idx on public.email_accounts(workspace_id,status);
create index audit_logs_workspace_created_idx on public.audit_logs(workspace_id,created_at desc);
create index jobs_claim_idx on public.jobs(status,run_after) where status='pending';
create index message_index_lookup_idx on public.message_index(email_account_id,received_at desc);
create index invitations_email_idx on public.workspace_invitations(email);

create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create function private.is_workspace_member(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.workspace_members m where m.workspace_id=target and m.user_id=(select auth.uid()) and m.status='active') $$;
create function private.has_workspace_role(target uuid, allowed public.workspace_role[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.workspace_members m where m.workspace_id=target and m.user_id=(select auth.uid()) and m.status='active' and m.role=any(allowed)) $$;
revoke all on function private.is_workspace_member(uuid) from public,anon,authenticated;
revoke all on function private.has_workspace_role(uuid,public.workspace_role[]) from public,anon,authenticated;
grant usage on schema private to authenticated;
grant execute on function private.is_workspace_member(uuid), private.has_workspace_role(uuid,public.workspace_role[]) to authenticated;

create function private.claim_job(worker_id text, lease_seconds int) returns public.jobs language plpgsql security definer set search_path='' as $$
declare claimed public.jobs;
begin
  update public.jobs set status='running',lease_owner=worker_id,lease_expires_at=now()+make_interval(secs=>least(greatest(lease_seconds,5),3600)),attempts=attempts+1,updated_at=now()
  where id=(select id from public.jobs where status='pending' and run_after<=now() and (lease_expires_at is null or lease_expires_at<now()) order by run_after for update skip locked limit 1)
  returning * into claimed; return claimed;
end $$;
revoke all on function private.claim_job(text,int) from public,anon,authenticated;

alter table public.profiles enable row level security; alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.workspace_invitations enable row level security; alter table public.email_accounts enable row level security; alter table public.email_account_settings enable row level security; alter table public.provider_credentials enable row level security; alter table public.mailbox_permissions enable row level security; alter table public.mcp_clients enable row level security; alter table public.mcp_credentials enable row level security; alter table public.mcp_mailbox_grants enable row level security; alter table public.message_index enable row level security; alter table public.drafts enable row level security; alter table public.sync_cursors enable row level security; alter table public.jobs enable row level security; alter table public.webhook_events enable row level security; alter table public.audit_logs enable row level security; alter table public.workspace_settings enable row level security; alter table public.system_settings enable row level security;

create policy profile_self on public.profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy workspace_read on public.workspaces for select to authenticated using((select private.is_workspace_member(id)));
create policy workspace_admin_update on public.workspaces for update to authenticated using((select private.has_workspace_role(id,array['owner','admin']::public.workspace_role[]))) with check((select private.has_workspace_role(id,array['owner','admin']::public.workspace_role[])));
create policy member_read on public.workspace_members for select to authenticated using((select private.is_workspace_member(workspace_id)));
create policy member_admin on public.workspace_members for all to authenticated using((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]))) with check((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[])));
create policy invitation_admin on public.workspace_invitations for all to authenticated using((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]))) with check((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[])));
create policy accounts_read on public.email_accounts for select to authenticated using((select private.is_workspace_member(workspace_id)) and (exists(select 1 from public.workspace_members m where m.workspace_id=email_accounts.workspace_id and m.user_id=(select auth.uid()) and m.role in('owner','admin')) or exists(select 1 from public.mailbox_permissions p where p.email_account_id=email_accounts.id and p.user_id=(select auth.uid()) and p.can_read)));
create policy accounts_admin on public.email_accounts for all to authenticated using((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]))) with check((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[])));
create policy mailbox_permissions_admin on public.mailbox_permissions for all to authenticated using((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]))) with check((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[])));

-- Tenant tables with a direct workspace_id use the same isolation boundary.
create policy account_settings_member on public.email_account_settings for select to authenticated using(exists(select 1 from public.email_accounts a where a.id=email_account_id and (select private.is_workspace_member(a.workspace_id))));
create policy account_settings_admin on public.email_account_settings for all to authenticated using(exists(select 1 from public.email_accounts a where a.id=email_account_id and (select private.has_workspace_role(a.workspace_id,array['owner','admin']::public.workspace_role[])))) with check(exists(select 1 from public.email_accounts a where a.id=email_account_id and (select private.has_workspace_role(a.workspace_id,array['owner','admin']::public.workspace_role[]))));
-- Provider credentials and MCP credential hashes intentionally have no authenticated policies; server-only secret key access.
create policy clients_member_read on public.mcp_clients for select to authenticated using((select private.is_workspace_member(workspace_id)));
create policy clients_admin on public.mcp_clients for all to authenticated using((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]))) with check((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[])));
create policy message_index_read on public.message_index for select to authenticated using((select private.is_workspace_member(workspace_id)));
create policy drafts_member on public.drafts for all to authenticated using((select private.is_workspace_member(workspace_id))) with check((select private.is_workspace_member(workspace_id)));
create policy jobs_member_read on public.jobs for select to authenticated using(workspace_id is not null and (select private.is_workspace_member(workspace_id)));
create policy audit_member_read on public.audit_logs for select to authenticated using(workspace_id is not null and (select private.is_workspace_member(workspace_id)));
create policy workspace_settings_read on public.workspace_settings for select to authenticated using((select private.is_workspace_member(workspace_id)));
create policy workspace_settings_admin on public.workspace_settings for all to authenticated using((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]))) with check((select private.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[])));

grant select,insert,update,delete on public.profiles,public.workspaces,public.workspace_members,public.workspace_invitations,public.email_accounts,public.email_account_settings,public.mailbox_permissions,public.mcp_clients,public.message_index,public.drafts,public.jobs,public.audit_logs,public.workspace_settings to authenticated;
revoke all on public.provider_credentials,public.mcp_credentials,public.system_settings,public.webhook_events,public.sync_cursors from anon,authenticated;
commit;
